{"code": "const [a, b, c] = await Promise.all([
  tools.grep({ pattern: "S1888|S1887|S1886|S1885|S1884|S1883|S1882|S1881", path: "coord" }),
  tools.grep({ pattern: "S1888", path: "." }),
  tools.grep({ pattern: "S1881|S1880|S1882", path: "AUDIT_LEDGER.md" }),
]);
console.log("=== coord matches ===");
for (const m of a.matches.slice(0,80)) console.log(m.path+":"+m.lineNumber+": "+m.line.slice(0,220));
console.log("\n=== S1888 anywhere ("+b.matches.length+") ===");
for (const m of b.matches.slice(0,60)) console.log(m.path+":"+m.lineNumber+": "+m.line.slice(0,220));
console.log("\n=== ledger S188x ===");
for (const m of c.matches.slice(-40)) console.log(m.lineNumber+": "+m.line.slice(0,220));
", "description": "Search coord and ledger for S1888 context"}

